"""Where an alert goes: the escalation for this service and severity if there is
one, otherwise the owning team from the service and the channel from the severity."""
import csv
from pathlib import Path

HERE = Path(__file__).parent


def _rows(name):
    with (HERE / name).open() as f:
        return list(csv.DictReader(f))


OWNERS = {r["service"]: r["team"] for r in _rows("service_owners.csv")}
CHANNELS = {r["severity"]: r["channel"] for r in _rows("severity_channels.csv")}
ESCALATIONS = {(r["service"], r["severity"]): r["team"] for r in _rows("escalations.csv")}

for service, severity in ESCALATIONS:
    if service not in OWNERS or severity not in CHANNELS:
        raise ValueError(f"escalations.csv names unknown service or severity: {service}, {severity}")


def route(service, severity):
    team = ESCALATIONS.get((service, severity), OWNERS[service])
    return team, CHANNELS[severity]

