"""Shipping price for one parcel: zone base rate times weight-band multiplier,
plus the zone's heavy surcharge when the band is heavy. All pricing data is in the CSVs."""
import csv
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path

HERE = Path(__file__).parent


def _flag(value):
    if value not in ("Y", "N"):
        raise ValueError("heavy must be Y or N, got %r" % value)
    return value == "Y"


def _load():
    with (HERE / "zone_rates.csv").open() as f:
        zones = {r["zone"]: (Decimal(r["base_rate"]), Decimal(r["heavy_surcharge"]))
                 for r in csv.DictReader(f)}
    with (HERE / "weight_bands.csv").open() as f:
        bands = [(r["band"], float(r["min_kg"]), float(r["max_kg"]),
                  Decimal(r["multiplier"]), _flag(r["heavy"]))
                 for r in csv.DictReader(f)]
    for prev, cur in zip(bands, bands[1:]):
        if prev[2] != cur[1]:
            raise ValueError("bands %s and %s do not meet" % (prev[0], cur[0]))
    return zones, bands


ZONES, BANDS = _load()


def price(zone, weight_kg):
    for _, lo, hi, multiplier, heavy in BANDS:
        if lo <= weight_kg < hi:
            break
    else:
        raise ValueError("no band for %.1f kg" % weight_kg)
    base, surcharge = ZONES[zone]
    raw = base * multiplier + (surcharge if heavy else Decimal("0"))
    return raw.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

