"""Prototype: one formula, every rule read from the CSVs."""
import csv
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path

HERE = Path(__file__).parent


def _load():
    with (HERE / "zone_rates.csv").open() as f:
        zones = {r["zone"]: r for r in csv.DictReader(f)}
    with (HERE / "weight_bands.csv").open() as f:
        bands = list(csv.DictReader(f))
    return zones, bands


ZONES, BANDS = _load()


def band_for(weight_kg):
    for r in BANDS:
        if float(r["min_kg"]) <= weight_kg < float(r["max_kg"]):
            return r["band"]
    raise ValueError("no band for %.1f kg" % weight_kg)


def price(zone, weight_kg):
    band = band_for(weight_kg)
    z = ZONES[zone]
    b = next(r for r in BANDS if r["band"] == band)
    total = Decimal(z["base_rate"]) * Decimal(b["multiplier"])
    if z["remote"] == "yes":
        total += Decimal(b["remote_surcharge"])
    return total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

